const message = $input.first().json.message || {};
const textMsg = (message.text || "").toString().toLowerCase().trim();

// Treat stickers, photos, voice, video as greetings
const isMedia = !!(message.sticker || message.photo || message.voice || message.video || message.document || message.audio);

const greetingPatterns = [
  "hi", "hello", "hey", "help", "start", "/start", "menu",
  "مرحبا", "مرحباً", "السلام عليكم", "وعليكم السلام", "سلام",
  "هلا", "هلو", "صباح الخير", "مساء الخير", "كيفك", "كيف الحال",
  "👋", "👍", "🙏", "😊", "✌️"
];

const isGreetingWord = greetingPatterns.includes(textMsg);
const isGreetingPattern = /^(hi+|hello+|hey+|مرحب|سلام|هلا|👋|👍|🙏)/i.test(textMsg);
const isShortNonQuery = textMsg.length > 0 && textMsg.length < 6 && !/[a-z]{2,}\d+/i.test(textMsg);

const isGreeting = isMedia || isGreetingWord || isGreetingPattern || (isShortNonQuery && !textMsg.match(/cow|cwn|site|fuel|فيول|بيانات/i));

return [{
  json: {
    ...($input.first().json),
    isGreeting,
    chatInput: message.text || (message.sticker ? "[sticker]" : "[media]")
  }
}];
